BEGIN;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='500ms';
DO $payload$
DECLARE payload jsonb; data jsonb; started timestamptz:=clock_timestamp();
BEGIN
  IF NOT pg_try_advisory_xact_lock(hashtextextended('comparator_strict:atomic-v1',0))
    OR NOT EXISTS(SELECT 1 FROM comparator_strict.execution_jobs WHERE job_key='ce1-ce200-eb4a74c1953f11a410c04232426c' AND status='running' AND operation_hash='eb4a74c1953f11a410c04232426c84584ab606dd2e42fee04b86b0b1f22042ee' AND deadline_at>clock_timestamp()) THEN RAISE EXCEPTION 'ce200_lease'; END IF;
  SELECT coalesce(jsonb_agg(to_jsonb(q)),'[]'::jsonb) INTO data FROM (SELECT l.*,md5(to_jsonb(l)::text) AS source_row_md5 FROM public.catalog_location_prices l
      WHERE l.store='plusfresc' AND l.product_id IN (SELECT id FROM public.plusfresc_products WHERE published IS TRUE AND (display_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)' OR category_name ~* '(agua|aigua|water|yogu|yogh|iogur|patat|papat)|b[ií]fidus' OR category_id IN ('020101','020102') OR category_id LIKE '0404%'))
      AND l.id COLLATE "C" > 'plusfresc:58:025866' COLLATE "C" ORDER BY l.id COLLATE "C" LIMIT 200) q;
  payload:=jsonb_build_object('job_key','ce1-ce200-eb4a74c1953f11a410c04232426c','operation_hash','eb4a74c1953f11a410c04232426c84584ab606dd2e42fee04b86b0b1f22042ee',
    'project_ref','gkffvigcnsesbaihycay','captured_at',started,'kind','locations','store','plusfresc',
